package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string           // PIC X len=1 = "N"
var WsInterest decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal    // PIC 9(11)V99 len=13 = 0
var WsCount int64              // PIC 9(5) len=5 = 0
var WsPrinEd string             // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string              // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string            // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var loanFile *os.File
var scanner *bufio.Scanner
var scannerDone bool
var inputDone bool

func pow10Decimal(n int32) decimal.Decimal {
	return decimal.New(1, n)
}

// storeDecimal simulates COBOL storage overflow: keep low-order digits that fit.
// value is assumed already rounded/truncated to scale.
// intDigits is number of integer digits in picture.
// scale is number of decimal digits.
func storeDecimal(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if intDigits <= 0 {
		return value
	}
	mod := pow10Decimal(int32(intDigits))
	if value.IsNegative() {
		abs := value.Abs()
		q := abs.Div(mod).Truncate(0)
		r := abs.Sub(q.Mul(mod))
		return r.Neg()
	}
	q := value.Div(mod).Truncate(0)
	r := value.Sub(q.Mul(mod))
	return r
}

// formatEdited formats a decimal value according to a numeric-edited picture
// containing Z,9,',','.' . High-order overflow digits are dropped.
func formatEdited(value decimal.Decimal, pic string) string {
	// determine scale = number of placeholder chars after '.'
	dotPos := strings.Index(pic, ".")
	scale := 0
	integerPicPart := pic
	decimalPicPart := ""
	if dotPos >= 0 {
		integerPicPart = pic[:dotPos]
		decimalPicPart = pic[dotPos+1:]
		for _, ch := range decimalPicPart {
			if ch == 'Z' || ch == '9' {
				scale++
			}
		}
	}
	// collect placeholder positions for integer part
	intPlaceIdxs := []int{}
	for i, ch := range integerPicPart {
		if ch == 'Z' || ch == '9' {
			intPlaceIdxs = append(intPlaceIdxs, i)
		}
	}
	intSlots := len(intPlaceIdxs)

	// collect decimal placeholder positions (relative to full pic)
	decPlaceIdxs := []int{}
	if dotPos >= 0 {
		for i := dotPos + 1; i < len(pic); i++ {
			ch := rune(pic[i])
			if ch == 'Z' || ch == '9' {
				decPlaceIdxs = append(decPlaceIdxs, i)
			}
		}
	}

	absVal := value.Abs()

	// get string representation with exactly scale decimals
	var s string
	if scale > 0 {
		// Use StringFixed which rounds; value is already at correct scale so rounding is neutral
		// Ensure we truncate/round to scale first to avoid extra digits
		// Use Round to not add unexpected rounding, but StringFixed also rounds.
		// So truncate to scale if needed: we assume value already has at most scale decimals.
		s = absVal.StringFixed(int32(scale))
	} else {
		s = absVal.Truncate(0).StringFixed(0)
	}
	parts := strings.SplitN(s, ".", 2)
	intPartStr := parts[0]
	fracPartStr := ""
	if scale > 0 {
		if len(parts) == 2 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
		// ensure length scale
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		} else if len(fracPartStr) > scale {
			fracPartStr = fracPartStr[:scale]
		}
	}

	// handle sign for intPartStr negative not expected
	if strings.HasPrefix(intPartStr, "-") {
		intPartStr = intPartStr[1:]
	}
	// integer overflow: keep low-order digits
	if len(intPartStr) > intSlots {
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	} else if len(intPartStr) < intSlots {
		intPartStr = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	}
	// integerDigitsStr length == intSlots
	integerDigitsStr := intPartStr

	// build output rune slice initialized with picture literals
	out := []rune(pic)

	// fill integer placeholders with digits
	for j, pos := range intPlaceIdxs {
		out[pos] = rune(integerDigitsStr[j])
	}
	// fill decimal placeholders
	for j, pos := range decPlaceIdxs {
		if j < len(fracPartStr) {
			out[pos] = rune(fracPartStr[j])
		} else {
			out[pos] = '0'
		}
	}

	// suppression for integer part
	if intSlots > 0 {
		firstNonZero := -1
		for idx, ch := range integerDigitsStr {
			if ch != '0' {
				firstNonZero = idx
				break
			}
		}
		if firstNonZero == -1 {
			// all zeros -> keep last '9' as zero
			firstNonZero = intSlots - 1
		}
		firstNonZeroPicPos := intPlaceIdxs[firstNonZero]
		for j, pos := range intPlaceIdxs {
			if j < firstNonZero {
				// Suppressed
				if pic[pos] == 'Z' {
					out[pos] = ' '
				} else { // '9' before first non-zero would be '0' but keep as '0' ? spec says 9 always prints; however if j < firstNonZero and digit 0, 9 would print 0. But this case only when leading 9 is zero and still suppressed? In our pictures 9 is trailing, so j < firstNonZero never includes trailing 9 when all zeros (firstNonZero is last). So spaces for Z.
					out[pos] = rune(integerDigitsStr[j])
				}
			} else {
				// not suppressed: keep digit (already)
			}
		}
		// commas
		for i, ch := range pic {
			if ch == ',' {
				if i < firstNonZeroPicPos {
					out[i] = ' '
				} else {
					out[i] = ','
				}
			}
		}
	}
	// ensure '.' remains '.'
	return string(out)
}

func formatCount(cnt int64) string {
	// PIC 9(5) zero-padded, high-order dropped
	s := fmt.Sprintf("%d", cnt)
	if len(s) > 5 {
		s = s[len(s)-5:]
	} else if len(s) < 5 {
		s = strings.Repeat("0", 5-len(s)) + s
	}
	// negative not expected
	if cnt < 0 {
		// handle sign? just pad
		s = fmt.Sprintf("%05d", cnt)
		if len(s) > 5 {
			s = s[len(s)-5:]
		}
	}
	return s
}

func parseNumericField(s string, scale int32) decimal.Decimal {
	// s is raw bytes possibly spaces
	trim := strings.TrimSpace(s)
	if trim == "" {
		return decimal.NewFromInt(0)
	}
	// trim may contain sign? Not in this program
	// Keep only digits and possibly sign
	// Remove any non-digit except leading sign
	sign := ""
	if strings.HasPrefix(trim, "+") || strings.HasPrefix(trim, "-") {
		sign = trim[:1]
		trim = trim[1:]
	}
	// keep digits only
	digits := ""
	for _, ch := range trim {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(sign + digits)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	if scale != 0 {
		d = d.Shift(-scale)
	}
	return d
}

func parseIntField(s string) int64 {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return 0
	}
	var v int64 = 0
	for _, ch := range trim {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	// handle overflow keep low-order digits? PIC 9(2) => modulus 100
	// But parsing already gives low value if truncated string length 2; overflow not needed
	return v
}

func parseLoanLine(line string) LoanRec {
	// line padded to 21 with spaces on right
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	rec := LoanRec{}
	rec.LrAcct = line[0:6]
	rec.LrPrincipal = parseNumericField(line[6:15], 2)
	rec.LrRate = parseNumericField(line[15:19], 2)
	rec.LrYears = parseIntField(line[19:21])
	return rec
}

func READ_PARA() {
	if scanner == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		// scanner strips newline, but we need raw line length handling (spaces preserved except newline)
		// LINE SEQUENTIAL: trailing spaces may be trimmed by scanner? Scanner keeps spaces except newline.
		// Pad handling done in parseLoanLine
		loanRec = parseLoanLine(line)
	} else {
		// EOF or error
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputDone = true
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	div := prod.Shift(-2) // divide by 100
	rounded := div.Round(2)
	// store with overflow
	WsInterest = storeDecimal(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	sum := WsTotal.Add(WsInterest)
	// truncate to 2 decimals (ADD without ROUNDED) then overflow
	sum = sum.Truncate(2)
	WsTotal = storeDecimal(sum, 11, 2)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}
	// MOVE to edited
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is X(6) exactly 6 chars
	acct := loanRec.LrAcct
	if len(acct) < 6 {
		acct = acct + strings.Repeat(" ", 6-len(acct))
	} else if len(acct) > 6 {
		acct = acct[:6]
	}
	fmt.Printf("%s %s %s\n", acct, WsPrinEd, WsIntEd)

	// PERFORM READ-PARA
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsInterest = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0
	inputDone = false

	loanFile, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			// treat as empty file
			scanner = nil
			inputDone = true
			WsEofFlag = "Y"
			// still need to run summary path as per MAIN-PARA
			// MAIN-PARA sequence: OPEN, READ, PROCESS UNTIL, CLOSE, SUMMARY
			// If file doesn't exist, OPEN fails in COBOL; but we simulate empty
			SUMMARY_PARA()
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer loanFile.Close()
	scanner = bufio.NewScanner(loanFile)
	// Allow longer lines; default 64k is fine
	// Preserve handling of long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE LOAN-FILE already deferred
	SUMMARY_PARA()
}
